def latex_in_to_pt(inches): return inches * 72.27

def latex_pt_to_in(pts): return pts / 72.27

def make_pdf_to_png_converter(): return None

def mpl_in_to_pt(inches): return inches * 72.0

def mpl_pt_to_in(pts): return pts / 72.0
